import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第07章 第一件东西","description":"","frontmatter":{},"headers":[],"relativePath":"第07章_第一件东西.md","filePath":"第07章_第一件东西.md"}'),r={name:"第07章_第一件东西.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第07章-第一件东西" tabindex="-1">第07章 第一件东西 <a class="header-anchor" href="#第07章-第一件东西" aria-label="Permalink to &quot;第07章 第一件东西&quot;">​</a></h1><p>开学第一天，校门口挤得走不动。</p><p>家长送到路口就停了，车进不来，行李箱的轮子在地上磨出一片响。有人提着被子，有人拎着一兜水果，还有人背着鼓鼓的书包从人群里侧着身子往前挤。我背着包，手上拎一个蛇皮袋，里面是奶奶晒的萝卜干和一罐腌菜。</p><p>宿舍还是那间，六个人，上下铺。我睡下铺，靠窗。上铺的兄弟叫周奕，假期长了十斤，一见面就拍肚子给我看。</p><p>他说，你这个假期干嘛去了，人都蔫了。</p><p>我说，在家。</p><p>他说，在家能蔫成这样。</p><p>我没接。</p><p>收拾完东西已经傍晚。我把课本从袋子里拿出来，一本一本码在床头的书架上。顺手拿抹布把桌子擦了一遍。桌子是旧的，木头上有别人刻的字，刻的是一个人的名字，后面还加了一个叉。</p><p>晚饭前去门卫室取了家里的东西。奶奶托人带了一袋衣服，还有一张纸条，上面写着让我按时吃饭。她不会写字，那纸条是邻居帮她写的。</p><p>晚上自修到九点。教室里是那种长条的日光灯，一盏一盏排过去，有一盏一直在闪，没人报修。我坐在第三组的中间，前面是个女生，头发扎得很高，背影跟所有人都很像。</p><p>我写到一半忽然想起来，她还不知道我长什么样。</p><p>我连她也不知道。</p><p>第二天放学，我从门卫室外面经过。墙上挂着一块小黑板，用粉笔写着今天有快递的人的名字。平时那上面最多写两三个，那天写了半行。</p><p>我扫了一眼，没细看。</p><p>走出七八步，我又退回来。</p><p>最后一行写着我的名字。</p><p>我在那块黑板前站了两秒。粉笔字写得很潦草，第一个字写得特别大，像是随手划的。我伸手碰了一下，指尖上沾了一层白粉。</p><p>门卫老头翻了半天，从一堆信件里抽出一个信封。牛皮纸的，不大，鼓起来一点，像里面装了什么硬的东西。他让我签了个字，那本子上前面几页都是别的同学的名字。</p><p>信封上没有寄件人。</p><p>我把信封揣在校服口袋里，一路走回去。上楼梯的时候手一直按着那个口袋，怕它掉出来。</p><p>回到宿舍，我把门关上，坐在床沿拆。</p><p>里面是一张卡。</p><p>卡是硬的，比明信片小一点，边缘剪得不齐，有一道剪歪的口子。她用铅笔画了一幅画。</p><p>画的是两个房子。</p><p>一个歪歪扭扭，墙是斜的，屋顶上有个洞；另一个小一点，挤在旁边，跟第一个错开半个身位。两个房子中间，画了一条很粗的线，把那条缝填得满满的。</p><p>房子前面画了两个小人。一个站着，另一个蹲在地上，看不清脸。</p><p>画的下面写了一行字。</p><p>她说：这是我们家。</p><p>我把那张卡翻过来。背面是空白的，只在右下角有一个小小的签名，写得很潦草，我看不清是什么。</p><p>我把卡夹进数学课本。</p><p>那本书是我包了书皮的，牛皮纸，用胶带粘的。我翻到中间，把卡夹在两页之间，合上，放回书架。</p><p>上铺的周奕从上面探下头，问我刚才在干什么。</p><p>我说，没什么。</p><p>他说，你脸红了。</p><p>我说，没有。</p><p>他说，你自己去照照。</p><p>后来那几天，我一有空就把那本数学书抽出来。不翻，就捏在手里，感受那一层薄薄的硬。有时候我会翻到那一页，把卡看一眼，再合上。</p><p>那时候我还不知道她长什么样。我连她是不是真的会画画都不确定。可我把那张画看了很多遍，看到闭上眼睛都能记起那两个房子的位置。</p><p>开学之后，她的消息少了。</p><p>以前一天几十条，现在一天三五条。有时候一整天都没有。</p><p>我数过。</p><p>第一天，我发了两条，她回了一条。 第二天，我发了三条，她没回。 第三天，她回了两条，都是很短的那种。</p><p>我不知道这是什么意思。我想，也许是学校管得紧。可是我又想，她当初放假的时候，一整天都抱着手机。</p><p>那几天我把手机放在桌肚里，每节课下课都拿出来看一次。屏幕是黑的，我就用指纹把它按亮，看到没有消息，再放回去。没有消息的时候，那个亮起来的屏幕反倒显得很笨。</p><p>周奕看出来了。他趴在课桌上问我，你这两天魂不守舍的，是不是有事。</p><p>我说，没有。</p><p>他说，你别以为我看不出来。</p><p>我说，真的没有。</p><p>他想了想，说了一句。他说，要么是家里的事，要么是人的事。</p><p>我说，都不是。</p><p>他说，那就是人的事。</p><p>我没反驳他。</p><p>第四天，我忍不住问了一句。</p><p>我说，你是不是不方便。</p><p>她隔了很久才回。</p><p>她说，不是。</p><p>她说，我在。</p><p>我说，那你为什么不说话。</p><p>她说，我不知道说什么。</p><p>我说，随便说点什么都行。</p><p>她说，我最近有点烦。</p><p>我问，怎么了。</p><p>她说，家里的事。</p><p>我说，那你说说。</p><p>她说，不想说。</p><p>然后她停了一会儿，发来一句。</p><p>她说，你有没有想我。</p><p>我说，有。</p><p>她说，有多想。</p><p>我在宿舍的床上躺着，上铺周奕已经睡着了，打呼噜。窗外的路灯照进来一条，落在地上。</p><p>我说，我数你一天发几条消息。</p><p>她过了很久才回。</p><p>她说，你有病。</p><p>她说完这三个字，又来一条。</p><p>她说，我也是。</p><p>她说完就不说了。那天夜里我把那本数学书从书架上拿下来，放在枕边。第二天早上醒来，书还在。</p><p>那张卡也在。夹在中间，一直夹着。</p><p>过了两天，我在办公室外面碰到了我们班主任。她叫我过去，问我这学期状态怎么样。我说还行。她说，你上学期进步不小，别松。我说好。</p><p>她说完正事，又问了一句。她说，你最近是不是心里有事。</p><p>我说没有。</p><p>她看了我一眼，说，有事就说，别一个人蔽着。</p><p>我说好。我说完这个字就往回走。走到楼梯口的时候，我又想起那张卡上画的两个房子。一歪一挤，中间那条粗线画得很用力，铅芯都划破了纸。</p><p>我那时候还不知道，那幅画以后会跟着我搬好几次家。</p>',84)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
